changeSet.sql:
ALTER TABLE clinlims.alert DROP CONSTRAINT IF EXISTS chk_alert_type;
ALTER TABLE clinlims.alert ADD CONSTRAINT chk_alert_type
CHECK (alert_type IN (
'FREEZER_TEMPERATURE', 'FREEZER_HUMIDITY', 'FREEZER_OFFLINE', 'EQUIPMENT_FAILURE',
'INVENTORY_LOW', 'SAMPLE_TRACKING', 'OTHER', 'EQA_DEADLINE', 'EQA_SUBMISSION_FAILED',
'SAMPLE_EXPIRATION', 'STAT_UPCOMING', 'STAT_OVERDUE', 'CRITICAL_UNACKNOWLEDGED',
'CRITICAL_RESULT', 'REFERRAL_CRITICAL_RESULT', 'REFERRAL_REJECTED',
'REQUIRED_BY_DEADLINE', 'MICROBIOLOGY_CRITICAL'
));
